package com.example.batterylow; import android.content.Context; import android.content.Intent; import android.content.IntentFilter; import android.os.BatteryManager; import android.os.Bundle; import android.widget.TextView; import androidx.appcompat.app.AppCompatActivity; public class MainActivity extends AppCompatActivity { final BatteryReceiver receiver=new BatteryReceiver(); TextView tvBattery; @Override protected void onCreate(Bundle b){super.onCreate(b);setContentView(R.layout.activity_main);tvBattery=findViewById(R.id.tvBattery);IntentFilter f=new IntentFilter();f.addAction(Intent.ACTION_BATTERY_LOW);f.addAction(Intent.ACTION_BATTERY_CHANGED);if(android.os.Build.VERSION.SDK_INT>=33)registerReceiver(receiver,f,Context.RECEIVER_EXPORTED);else registerReceiver(receiver,f);Intent s=registerReceiver(null,new IntentFilter(Intent.ACTION_BATTERY_CHANGED));if(s!=null){int level=s.getIntExtra(BatteryManager.EXTRA_LEVEL,-1),scale=s.getIntExtra(BatteryManager.EXTRA_SCALE,-1);int p=(int)((level*100f)/scale);tvBattery.setText("Battery Percentage : "+p+"%");}} @Override protected void onDestroy(){try{unregisterReceiver(receiver);}catch(Exception ignored){}super.onDestroy();}}
